#include "unity.h"
#include "header.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_calculate_ct_single_process(void) {
    // Setup: create a process queue with exactly one process.
    // This triggers the target path where:
    // - The initial while loop to create duplicate runs once and exits (ptr != NULL -> FOR_EXIT)
    // - The sorting while loop exits immediately (rpt != NULL -> FOR_EXIT because rpt = ptr->next = NULL)
    // - The main for loop (i < n - 1) exits because n=1, so i < 0 is false.
    struct node *root = NULL;
    int id = 1;
    int at = 0;
    int bt = 5;
    int priority = 1;

    insert(&root, id, at, bt, priority);

    // Test: call calculate_ct
    float avg = calculate_ct(&root);

    // Assertions
    // For a single process: CT = AT + BT = 0 + 5 = 5. Average CT = 5.0 / 1 = 5.0
    TEST_ASSERT_FLOAT_WITHIN(0.001, 5.0, avg);
    // Verify the original node was updated via update dependency.
    TEST_ASSERT_NOT_NULL(root);
    TEST_ASSERT_EQUAL_INT(5, root->CT); // CT should be 5
    TEST_ASSERT_EQUAL_INT(0, root->WT); // WT passed as 0 to update
    TEST_ASSERT_EQUAL_INT(0, root->TAT); // TAT passed as 0 to update

    // Cleanup
    helper_cleanup_process_queue(&root);
}


