        count++;
        ptr = ptr->next;
    }
    if (count > 0) {
        actual_avgCT /= count;
        actual_avgTAT /= count;
        actual_avgWT /= count;
    }
    TEST_ASSERT_FLOAT_WITHIN(tolerance, expected_avgCT, actual_avgCT);
